ROOT=Path(__file__).parent
def p(s): return '<p>'+s+'</p>'
def bullets(*items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def steps(*items): return '<ol>'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def table(headers,rows): return '<table><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</table>'
def sec(t,h): return {'title':t,'html':h}
def sheet(t,*f): return {'title':t,'fields':list(f)}
def visual(alt): return '<img src="@@핵심예시.png@@" alt="'+alt+'"/>'
