ADOBE2='https://helpx.adobe.com/kr/fonts/web/font-licensing/font-licensing.html'
def source(title,provider,url,scope,activity): return dict(title=title,provider=provider,url=url,scope=scope,activity=activity,language='ko',free=True,checked_at=now())
for index,item in enumerate(DATA):
    unit_index=index//3
    entry=read_json(ROOT/'runs.json')[unit_index]
    folder=Path(entry['run'])/'03_지원자료'/(item['group']+'그룹')
    if unit_index==0:
        sources=[source('프로토타입 연결','Figma Learn',FIGMA1,'인터랙션 추가와 트리거·액션·목적지 설명을 무료로 읽습니다.','자신의 주요 버튼 하나를 골라 누르는 요소와 실제 목적지 프레임을 대조하세요.'),source('프로토타입 흐름 생성 및 관리','Figma Learn',FIGMA2,'흐름 시작점과 흐름 이름 관리 부분을 무료로 읽습니다.','이번 실습의 시작점을 확인하고 실행 링크를 다시 열어 같은 과업이 시작되는지 확인하세요.')]
    else:
        sources=[source('효과적인 텍스트 프롬프트 작성','Adobe Firefly 도움말',ADOBE1,'구체적인 대상·설명·분위기를 적고 결과에 맞춰 질문을 고치는 부분을 무료로 읽습니다. 도구의 유료 기능 사용은 필수가 아닙니다.','기존 질문에서 모호한 조건 하나를 찾아 화면에 필요한 조건으로 고쳐 쓰고 실제 사용 기록과 연습 예시를 구분하세요.'),source('글꼴 라이선스 FAQ','Adobe Fonts 도움말',ADOBE2,'문서의 적용 대상과 사용 형태별 안내를 무료로 읽습니다. 자산 자체가 무료라는 뜻은 아닙니다.','자신이 쓴 글꼴의 제공처와 조건 확인 위치를 적으세요. Adobe Fonts 외 글꼴은 해당 제공처 안내를 찾아 기록합니다.')]
    content={k:item[k] for k in ('group','subtitle','sections','worksheets')}
    content.update(schema_version=1,example=False,unit=entry['job']['unit'],support_plan_sha256=entry['plans'][item['group']]['support_plan_sha256'],sources=sources,images=['핵심예시.png'],files=['학습자료.pdf','실습양식.docx','읽는순서.txt','핵심예시.png']+[f'빈칸양식/{i:02d}_실습.csv' for i in range(1,4)])
    write_json(folder/'content.json',content)
    cards=''.join('<div class="card"><div class="num">0'+str(i+1)+'</div><h2>'+escape(t)+'</h2><p>'+escape(d)+'</p></div>' for i,(t,d) in enumerate(item['diagram_nodes']))
    html='<!doctype html><html lang="ko"><meta charset="utf-8"><style>body{margin:0;font-family:Malgun Gothic,sans-serif;background:#f3f6fa;color:#17365a}main{width:1120px;box-sizing:border-box;padding:40px}h1{font-size:30px;margin:0 0 28px}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:white;border:1px solid #cbd8e6;border-top:5px solid #386f96;padding:20px 18px;min-height:155px;box-sizing:border-box}.num{font-size:15px;color:#60788d;font-weight:bold}h2{font-size:24px;margin:12px 0}p{font-size:20px;line-height:1.6;margin:0}.note{font-size:17px;margin-top:24px;color:#53677a}</style><main><h1>'+escape(item['diagram_title'])+'</h1><div class="flow">'+cards+'</div><p class="note">'+escape(item['diagram_note'])+'</p></main></html>'
    (folder/'diagram.html').write_text(html,encoding='utf-8')
